t.script:
//
(function () {

    /* ── Config from server ─────────────────────────────── */
    var meta        = document.getElementById('rc-meta');
    var fee         = parseFloat(meta.dataset.shippingFee) || 0;
    var cur         = meta.dataset.currency || '$';
    var disclaimer  = meta.dataset.disclaimer || '';
    var bonusPercent = parseFloat(meta.dataset.bonusPercent) || 0;

    /* ── State ──────────────────────────────────────────── */
    var configured  = {};   /* lineId → { name, qty, price, imgSrc, reasonId, reasonName, notes } */
    var currentLine = null; /* lineId being configured */
    var outcome     = null;
    var outcomeName = null;

    function fmt(n) { return cur + parseFloat(n).toFixed(2); }
    function esc(s) {
        return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
    }

    /* ── Fee helpers ────────────────────────────────────── */
    function computeEffectiveFee() {
        var items = Object.values(configured);
        if (!items.length) return fee;
        return items.every(function(c) { return c.feeWaived; }) ? 0 : fee;
    }

    function updateMethodPanel() {
        var ef = computeEffectiveFee();
        var feeEl = document.getElementById('method-fee-display');
        var subEl = document.getElementById('method-sub-display');
        if (feeEl) feeEl.textContent = ef ? fmt(ef) + ' AUD' : 'Free';
        if (subEl) {
            if (!ef) {
                subEl.textContent = '';
            } else if (outcome === 'exchange') {
                subEl.textContent = 'Return postage cost — billed against your exchange';
            } else if (outcome === 'store_credit') {
                subEl.textContent = fmt(ef) + ' will be deducted from your store credit';
            } else {
                subEl.textContent = fmt(ef) + ' will be deducted from your refund';
            }
        }
    }
    updateMethodPanel();

    /* ── Resolution filtering ────────────────────────────── */
    window.goToResolution = function() {
        var items = Object.values(configured);
        var conflictDiv = document.getElementById('resolution-conflict-warning');
        var optionsDiv = document.getElementById('resolution-options');

        // Detect mixed cart: warranty (exchange-only) + non-warranty items
        var hasExchangeOnly = items.some(function(c) { return (c.allowedResolution || 'any') === 'exchange'; });
        var hasNonWarranty  = items.some(function(c) { return (c.allowedResolution || 'any') !== 'exchange'; });

        if (hasExchangeOnly && hasNonWarranty) {
            conflictDiv.style.display = '';
            optionsDiv.style.display = 'none';
            document.querySelector('#view-resolution .rc-step-title').textContent = 'Separate returns required';
            showView('view-resolution');
            return;
        }

        conflictDiv.style.display = 'none';
        optionsDiv.style.display = '';

        var allRows = document.querySelectorAll('#view-resolution .rc-option-row');
        var allowed = new Set(['credit_note', 'store_credit', 'exchange']);
        items.forEach(function(c) {
            var ar = c.allowedResolution || 'any';
            if (ar === 'refund') { allowed.delete('store_credit'); allowed.delete('exchange'); }
            else if (ar === 'store_credit') { allowed.delete('credit_note'); allowed.delete('exchange'); }
            else if (ar === 'exchange') { allowed.delete('credit_note'); allowed.delete('store_credit'); }
        });
        if (allowed.size === 0) allowed = new Set(['credit_note', 'store_credit', 'exchange']);

        allRows.forEach(function(row) {
            var visible = allowed.has(row.dataset.outcome);
            row.style.display = visible ? '' : 'none';
            if (!visible && row.classList.contains('rc-selected')) {
                row.classList.remove('rc-selected');
                outcome = null; outcomeName = null;
                document.getElementById('btn-resolution-next').disabled = true;
            }
        });

        var visibleRows = Array.from(allRows).filter(function(r) { return r.style.display !== 'none'; });
        if (visibleRows.length === 1 && !visibleRows[0].classList.contains('rc-selected')) {
            visibleRows[0].click();
        }

        var titleEl = document.querySelector('#view-resolution .rc-step-title');
        if (titleEl) {
            titleEl.textContent = (allowed.size === 1 && allowed.has('exchange'))
                ? 'Warranty replacement' : 'How can we resolve it?';
        }
        showView('view-resolution');
    };

    window.goToMethodView = function() {
        updateMethodPanel();
        showView('view-method');
    };

    /* ── View switching ─────────────────────────────────── */
    var views = ['view-items','view-configure','view-resolution','view-method','view-review'];
    window.showView = function(id) {
        views.forEach(function(v){ document.getElementById(v).style.display = 'none'; });
        document.getElementById(id).style.display = '';
        window.scrollTo({top:0, behavior:'smooth'});
    };

    /* ── Item row clicks ────────────────────────────────── */
    document.querySelectorAll('.rc-item-row:not(.rc-item-disabled)').forEach(function(row){
        row.addEventListener('click', function(){
            var id = row.dataset.lineId;
            openConfigure(id, row);
        });
    });

    function openConfigure(lineId, rowEl) {
        currentLine = lineId;
        var row = rowEl || document.querySelector('[data-line-id="' + lineId + '"]');
        if (!row) return;

        /* Populate left panel */
        var left = document.getElementById('configure-left');
        var img  = row.dataset.img || '';
        var prev = configured[lineId];
        var maxQty = parseFloat(row.dataset.qty) || 1;
        left.innerHTML =
            '<img src="' + esc(img) + '" class="rc-split-left-img" onerror="this.style.visibility=\'hidden\'" alt=""/>' +
            '<div class="rc-split-left-name">' + esc(row.dataset.name) + '</div>' +
            '<div class="rc-split-left-price">' + fmt(parseFloat(row.dataset.price)||0) +
                ' &times; ' + maxQty + '</div>';

        /* Set qty input */
        var qtyInput = document.getElementById('configure-qty-input');
        if (qtyInput) {
            qtyInput.max = maxQty;
            qtyInput.value = prev ? prev.qty : maxQty;
        }

        /* If already configured, pre-select the reason */
        document.querySelectorAll('#configure-reasons .rc-option-row').forEach(function(r){
            r.classList.toggle('rc-selected', prev && r.dataset.reasonId == prev.reasonId);
        });

        /* Show correct sub-panel */
        if (prev) {
            document.getElementById('configure-notes').style.display = '';
            document.getElementById('configure-reasons').style.display = 'none';
            var ta = document.getElementById('configure-notes-text');
            if (ta) ta.value = prev.notes || '';
        } else {
            showConfigureReasons();
        }

        showView('view-configure');
    }

    window.editItem = function(btn) {
        openConfigure(btn.dataset.lineId);
    };

    window.removeItem = function(btn) {
        var id = btn.dataset.lineId;
        delete configured[id];
        refreshItemRow(id);
        updateItemsNext();
    };

    /* ── Reason selection ───────────────────────────────── */
    document.querySelectorAll('#configure-reasons .rc-option-row').forEach(function(row){
        row.addEventListener('click', function(){
            document.querySelectorAll('#configure-reasons .rc-option-row').forEach(function(r){ r.classList.remove('rc-selected'); });
            row.classList.add('rc-selected');
            /* Transition to notes sub-panel */
            document.getElementById('configure-reasons').style.display = 'none';
            var notesPanel = document.getElementById('configure-notes');
            notesPanel.style.display = '';
            document.getElementById('configure-notes-text').value = '';
        });
    });

    window.showConfigureReasons = function() {
        document.getElementById('configure-notes').style.display = 'none';
        document.getElementById('configure-reasons').style.display = '';
    };

    /* ── Confirm item config ────────────────────────────── */
    window.confirmItem = function() {
        var selReason = document.querySelector('#configure-reasons .rc-option-row.rc-selected');
        if (!selReason) return;
        var row = document.querySelector('[data-line-id="' + currentLine + '"]');
        if (!row) return;

        var qtyVal = parseFloat((document.getElementById('configure-qty-input') || {}).value);
        if (!qtyVal || qtyVal < 1) qtyVal = parseFloat(row.dataset.qty) || 1;
        var maxQty = parseFloat(row.dataset.qty) || qtyVal || 1;
        var lineTotal = parseFloat(row.dataset.price) || 0;
        configured[currentLine] = {
            name:       row.dataset.name,
            qty:        qtyVal,
            price:      parseFloat(row.dataset.price) || 0,
            selectedTotal: lineTotal * (qtyVal / maxQty),
            imgSrc:     row.dataset.img || '',
            reasonId:   selReason.dataset.reasonId,
            reasonName: selReason.dataset.reasonName,
            excludeEstimate: selReason.dataset.excludeEstimate === '1',
            allowedResolution: selReason.dataset.allowedResolution || 'any',
            feeWaived:  selReason.dataset.feeWaived === '1',
            notes:      (document.getElementById('configure-notes-text') || {}).value || '',
        };

        refreshItemRow(currentLine);
        updateItemsNext();
        showView('view-items');
    };

    function refreshItemRow(lineId) {
        var row     = document.querySelector('[data-line-id="' + lineId + '"]');
        var badge   = document.getElementById('badge-' + lineId);
        var actions = document.getElementById('badge-actions-' + lineId);
        var chevron = document.getElementById('chevron-' + lineId);
        if (!row) return;

        if (configured[lineId]) {
            row.classList.add('rc-configured');
            if (badge)   { badge.style.display = 'inline-flex'; badge.querySelector('.badge-qty').textContent = configured[lineId].qty; }
            if (actions) actions.style.display = 'inline-flex';
            if (chevron) chevron.style.display = 'none';
        } else {
            row.classList.remove('rc-configured');
            if (badge)   badge.style.display = 'none';
            if (actions) actions.style.display = 'none';
            if (chevron) chevron.style.display = '';
        }
    }

    function updateItemsNext() {
        document.getElementById('btn-items-next').disabled = Object.keys(configured).length === 0;
    }

    /* ── Resolution ─────────────────────────────────────── */
    document.querySelectorAll('#view-resolution .rc-option-row').forEach(function(row){
        row.addEventListener('click', function(){
            document.querySelectorAll('#view-resolution .rc-option-row').forEach(function(r){ r.classList.remove('rc-selected'); });
            row.classList.add('rc-selected');
            outcome     = row.dataset.outcome;
            outcomeName = row.dataset.outcomeName;
            var wrap = document.getElementById('exchange-wrap');
            wrap.style.display = (outcome === 'exchange') ? 'block' : 'none';
            document.getElementById('btn-resolution-next').disabled = false;
        });
    });

    /* ── Build review then show ─────────────────────────── */
    window.buildReviewAndShow = function() {
        /* Items HTML */
        var html = '';
        var total = 0;
        var count = 0;
        Object.entries(configured).forEach(function(e){
            var id = e[0], c = e[1];
            if (!c.excludeEstimate) {
                total += c.selectedTotal;
            }
            count++;
            var itemValue = c.excludeEstimate ? 'Warranty assessment' : fmt(c.selectedTotal);
            html += '<div class="rc-review-item">' +
                '<div class="d-flex justify-content-between align-items-start">' +
                '<div>' +
                '<div style="font-weight:600;font-size:.86rem;">' + esc(c.name) + '</div>' +
                '<div style="color:#888;font-size:.78rem;margin-top:.15rem;">' + esc(c.reasonName) + ' &rsaquo;</div>' +
                '</div>' +
                '<span style="color:#666;font-size:.82rem;">&times; ' + c.qty + '</span>' +
                '</div>' +
                '<div style="color:#888;font-size:.78rem;margin-top:.25rem;">' + itemValue + '</div>' +
                '</div>';
        });
        document.getElementById('review-items-html').innerHTML = html;

        /* Method */
        var ef = computeEffectiveFee();
        var methodHtml = '<strong>Ship with our return label (' + (ef ? fmt(ef) + ' AUD' : 'Free') + ')</strong>';
        if (ef) {
            var feeNote = outcome === 'exchange'
                ? 'Return postage cost — billed against your exchange'
                : fmt(ef) + ' will be deducted from your ' + (outcome === 'store_credit' ? 'store credit' : 'refund');
            methodHtml += '<br><span style="color:#888;font-size:.78rem;">' + feeNote + '</span>';
        }
        document.getElementById('review-method-html').innerHTML = methodHtml;

        /* Financial summary */
        document.getElementById('rv-items-label').textContent = 'Return item' + (count > 1 ? 's (' + count + ')' : ' (1)');
        document.getElementById('rv-item-val').textContent = outcome === 'exchange' ? 'Warranty assessment' : ('-' + fmt(total));

        var shipRow = document.getElementById('rv-shipping-row');
        var netTotal = Math.max(total - ef, 0);
        if (ef > 0 && outcome !== 'exchange') {
            shipRow.style.display = '';
            document.getElementById('rv-shipping').textContent = fmt(ef);
        } else {
            shipRow.style.display = 'none';
        }
        if (outcome === 'credit_note') {
            document.getElementById('rv-total-label').textContent = 'Estimated refund';
            document.getElementById('rv-total').textContent = fmt(netTotal) + ' AUD';
            document.getElementById('rv-outcome-note').textContent = 'Refund to original payment method';
        } else if (outcome === 'exchange') {
            shipRow.style.display = 'none';
            document.getElementById('rv-total-label').textContent = 'Outcome';
            document.getElementById('rv-total').textContent = 'Exchange';
            document.getElementById('rv-outcome-note').textContent = "We'll confirm the replacement once we receive the item.";
        } else {
            document.getElementById('rv-total-label').textContent = 'Estimated store credit';
            document.getElementById('rv-total').textContent = fmt(netTotal) + ' AUD';
            document.getElementById('rv-outcome-note').textContent = 'Issued after receipt and inspection';
        }

        /* Disclaimer */
        document.getElementById('rc-disclaimer-text').textContent = disclaimer;

        showView('view-review');
    };

    /* ── Inject hidden form inputs on submit ────────────── */
    document.getElementById('rc-form').addEventListener('submit', function(){
        document.querySelectorAll('.rc-dyn').forEach(function(e){ e.remove(); });

        function h(n, v) {
            var i = document.createElement('input');
            i.type = 'hidden'; i.name = n; i.value = v || ''; i.className = 'rc-dyn';
            document.getElementById('rc-form').appendChild(i);
        }

        Object.entries(configured).forEach(function(e){
            var id = e[0], c = e[1];
            h('line_ids', id);
            h('qty_' + id, c.qty);
            h('reason_id_' + id, c.reasonId);
            h('notes_' + id, c.notes);
        });
        h('reza_operation_type', outcome || '');
        var xn = document.getElementById('exchange-notes');
        if (xn) h('reza_exchange_preference', xn.value);
    });

    var termsToggle = document.getElementById('rc-terms-toggle');
    if (termsToggle) {
        termsToggle.addEventListener('click', function(ev) {
            ev.preventDefault();
            var panel = document.getElementById('rc-terms-panel');
            panel.style.display = panel.style.display === 'none' ? '' : 'none';
        });
    }

})();
//
